param(
    [Parameter(Mandatory= $true)]
    [string]$VersionHeader
)

# Comments 
$comments = @(
# Comment at the beginning of version header
@"
/*
 * This file is automatically written by build.ps1.
 * It automatically updates VERSIONINFO in .rc.
 *
 * Important:
 * - Do not edit define names.
 * - Do not convert defines to constexpr.
 * - Do not add '#pragma once' to the file.
 * - This file must be encoded in UTF-16 Litte Endian.
 *
 * If you are having problems building:
 * Delete file content and save as empty. It will be regenerated.
 */
"@,

# Comment before VERSION_BUILD
@"
/*
 * This define is incremented every build by build.ps1.
 * There is no need to edit this define manually (unless you really want to).
 */
"@,

# Comment before auto generated defines
@"
/*
 * These defines are automatically generated by build.ps1.
 * Editing these define values will do nothing.
 * If you mess these up at any point, you can delete them completely and they will be regenerated.
 */
"@
)

# Version names
$versionNames = @(
    "VERSION_MAJOR", 
    "VERSION_MINOR", 
    "VERSION_PATCH", 
    "VERSION_BUILD"
)

# File info entry names
$fileInfoEntryNames = @(
    "COMPANY_NAME",
    "FILE_DESCRIPTION",
    "INTERNAL_NAME",
    "LEGAL_COPYRIGHT",
    "ORIGINAL_FILENAME",
    "PRODUCT_NAME"
)

# Versions (populated by version header values)
# Note: The defined values here serve as default
$versions = @{
    VERSION_MAJOR = 1;
    VERSION_MINOR = 0;
    VERSION_PATCH = 0;
    VERSION_BUILD = 0;
}

# File info entries (populated by version header values)
# Note: The defined values here serve as default
$fileInfoEntries = @{
    COMPANY_NAME      = "KirKode Development";
    FILE_DESCRIPTION  = "A simple template for ImGui.";
    INTERNAL_NAME     = "ImGuiTemplate";
    LEGAL_COPYRIGHT   = "Copyright (C) 2026";
    ORIGINAL_FILENAME = "ImGuiTemplate.exe";
    PRODUCT_NAME      = "ImGui Template";
}

# Ensure version header exists
if (-not (Test-Path -LiteralPath $VersionHeader)) {
    throw "Version header not found: $VersionHeader"
}

# Read version header content
$bytes = [System.IO.File]::ReadAllBytes($VersionHeader)

# Decode vile header content to text
if ($bytes.Length -ge 2) {
    # See if encoding is UTF-16
    $unicode = $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE

    # Decode to text
    #$text
    if ($unicode) {
        $text = [System.Text.Encoding]::Unicode.GetString($bytes)
    } else {
        $text = [System.Text.Encoding]::UTF8.GetString($bytes)
        Write-Host "Version header wasn't encoded in Unicode. This can cause issues. Change file encoding to Unicode."
    }
    
    # Ensure '#pragma once' isn't present anywhere
    if ($text -match '(?m)^\s*#pragma\s+once') {
        throw "Version header contains #pragma once. Remove it."
    }

    # Ensure 'constexpr' isn't present anywhere
    if ($text -match 'constexpr ') {
        throw "Defines have been converted to constexpr. Change them back."
    }

    # Get version define values
    for ($i = 0; $i -lt $versionNames.Count; $i++) {
        if ($text -match "#define\s+$($versionNames[$i])\s+(\d+)") {
            $versions[$versionNames[$i]] = [int]$Matches[1]
        } else {
            Write-Host "Version define $($versionNames[$i]) not found. Falling back to default value."
        }
    }

    # Get file info entry values
    for ($i = 0; $i -lt $fileInfoEntryNames.Count; $i++) {
        if ($text -match "#define\s+$($fileInfoEntryNames[$i])\s+`"([^`"]*)`"") {
            $fileInfoEntries[$fileInfoEntryNames[$i]] = [string]$Matches[1]
        } else {
            Write-Host "File info entry define $($fileInfoEntryNames[$i]) not found. Falling back to default value."
        }
    }
} else {
    Write-Host "Version header is empty. Regenerating with default values."
}

# Increment VERSION_BUILD
$versions["VERSION_BUILD"]++

# Build new content
$commaSeparatedVersions = 
    "$($versions[$versionNames[0]])," + 
    "$($versions[$versionNames[1]])," + 
    "$($versions[$versionNames[2]])," + 
    "$($versions[$versionNames[3]])"

$periodSeparatedVersions = 
    "$($versions[$versionNames[0]])." + 
    "$($versions[$versionNames[1]])." + 
    "$($versions[$versionNames[2]])." + 
    "$($versions[$versionNames[3]])"

$newContent = @(
@"
$($comments[0])

#define COMPANY_NAME "$($fileInfoEntries["COMPANY_NAME"])"
#define FILE_DESCRIPTION "$($fileInfoEntries["FILE_DESCRIPTION"])"
#define INTERNAL_NAME "$($fileInfoEntries["INTERNAL_NAME"])"
#define LEGAL_COPYRIGHT "$($fileInfoEntries["LEGAL_COPYRIGHT"])"
#define ORIGINAL_FILENAME "$($fileInfoEntries["ORIGINAL_FILENAME"])"
#define PRODUCT_NAME "$($fileInfoEntries["PRODUCT_NAME"])"

#define VERSION_MAJOR $($versions["VERSION_MAJOR"])
#define VERSION_MINOR $($versions["VERSION_MINOR"])
#define VERSION_PATCH $($versions["VERSION_PATCH"])

$($comments[1])
#define VERSION_BUILD $($versions["VERSION_BUILD"])

$($comments[2])
#define VERSION_FILE $commaSeparatedVersions
#define VERSION_PRODUCT $commaSeparatedVersions
#define VERSION_FILE_STRING "$periodSeparatedVersions"
#define VERSION_PRODUCT_STRING "$periodSeparatedVersions"

/*
 * Version: $periodSeparatedVersions
 */
"@
)

# Write new version header 
$utf16 = New-Object System.Text.UnicodeEncoding $false, $true
[System.IO.File]::WriteAllText($VersionHeader, $newContent, $utf16)
Write-Host "Wrote new version header: Version=$periodSeparatedVersions"